                "absolute": 0,
                "relative": 0
              }
            ]
          }
        ]
      },
      "completion": {
        "scope": "New adaptor 2026-10-25: schemaxis.flac/1 encodeLossless and decodePCM16 routes, independent PCM16 WAV reader and writer, STREAMINFO/metadata/first-frame checks, fixed native flac 1.5 stages, fresh trusted native decode verification, discovery, guidance, Studio starters and bounded native acceptance against FLAC 1.5.0.",
        "review": [
          "verification/2026-10-25-flac.md",
          "verification/2026-10-25-flac-55.md"
        ],
        "notApplicable": {
          "native-inspection": "No interactive native inspection; the audio file and its JSON summary are ordinary publications.",
          "mpi": "The recipe is serial; each native process is a single thread.",
          "time-batches": "No temporal batching; common finite studies remain available.",
          "live-editing": "No persistent native session; edit JSON then create a new bounded run.",
          "native-save": "FLAC and WAV publications are supported; there is no application session or project save."
        }
      }
    }
  }
}
